// Desktop-branded logo: repository appicon.png encoded as a data URI.

import type { IconProps } from './icons/props.ts'

const LOGO_DATA_URI = 'data:image/png;base64,'

/**
 * Render the branded logo mark.
 * @param props.size - width in px (default 24).
 * @param props.className - extra class for layout placement.
 * @returns the logo img (aria-hidden decorative brand art).
 */
export function FishLogo({ size = 24, className }: IconProps) {
  return (
    <img
      src={LOGO_DATA_URI}
      alt=""
      aria-hidden="true"
      width={size}
      height="auto"
      className={className}
      style={{ display: 'block' }}
    />
  )
}
